tasks.solution:
def missing_ids(expected, received):
    known = set(received)
    missing = []
    for key in expected:
        if key not in known:
            known.add(key)
            missing.append(key)
    return missing

def error_rows(lines):
    import json
    errors = []
    for i, line in enumerate(lines, 1):
        try:
            item = json.loads(line)
        except json.JSONDecodeError:
            errors.append(i)
            continue
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or not item['id'].strip():
            errors.append(i)
    return errors

