tasks.solution:
def chunks(values, size):
    group = []
    for item in values:
        group.append(item)
        if len(group) == size:
            yield group
            group = []
    if group:
        yield group

def audit_csv(text):
    import csv
    from io import StringIO
    ok = bad = 0
    for row in csv.DictReader(StringIO(text)):
        try:
            minutes = int(row['minutes'])
        except (TypeError, ValueError):
            bad += 1
            continue
        if row['id'].strip() and minutes >= 0:
            ok += 1
        else:
            bad += 1
    return ok, bad
